"""classify the logical group generated by symmetry actions in Sp(2k,2), for any k.

basis convention is (x_1..x_k | z_1..z_k) with matrices acting on column vectors, as in bb_logical_action.
exact order comes from a faithful permutation action on the orbits of the basis vectors plus schreier-sims,
which is cheap whenever the group is small; large groups are reported as such, never guessed.
"""
from __future__ import annotations
import numpy as np
from bb_clifford_order import sp_order, _to_rows, _apply, generates_full_clifford
from gate_naming import name_gate


def _arr(M):
    return np.array([[int(x) for x in row] for row in M], dtype=np.uint8)


def _block(M, k, i, j):
    return M[np.ix_([i, k + i], [j, k + j])]


def _nonzero_blocks(M, k):
    return {(i, j) for i in range(k) for j in range(k) if _block(M, k, i, j).any()}


def clusters_of(mats, k):
    """connected components of logical qubits under off-diagonal 2x2 blocks of any generator."""
    parent = list(range(k))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for M in mats:
        for i, j in _nonzero_blocks(M, k):
            if i != j:
                parent[find(i)] = find(j)
    groups = {}
    for q in range(k):
        groups.setdefault(find(q), []).append(q)
    return sorted(groups.values())


def restrict(M, qubits, k):
    idx = list(qubits) + [k + q for q in qubits]
    return M[np.ix_(idx, idx)]


def exact_order(mats, k, max_points=3000):
    """order of the matrix group via faithful action on orbits of basis vectors; (None, reason) past the point cap."""
    n = 2 * k
    rows = [_to_rows(M, n) for M in mats]
    points, index = [], {}
    for b in range(n):
        v0 = 1 << b
        if v0 in index:
            continue
        stack = [v0]
        index[v0] = None
        while stack:
            v = stack.pop()
            points.append(v)
            if len(points) > max_points:
                return None, f"orbit of basis vectors exceeds {max_points} points"
            for r in rows:
                w = _apply(v, r, n)
                if w not in index:
                    index[w] = None
                    stack.append(w)
    pos = {v: i for i, v in enumerate(points)}
    perms = [[pos[_apply(v, r, n)] for v in points] for r in rows]
    from sympy.combinatorics import Permutation, PermutationGroup
    return int(PermutationGroup([Permutation(p) for p in perms]).order()), "exact"


def classify_generator(M, k):
    """structural type of one 2k x 2k action, naming local gates and permutations where it is monomial."""
    I = np.eye(2 * k, dtype=np.uint8)
    if (M == I).all():
        return {"type": "identity"}
    blocks = _nonzero_blocks(M, k)
    rows_used, cols_used = {i for i, _ in blocks}, {j for _, j in blocks}
    if len(blocks) == k and len(rows_used) == k and len(cols_used) == k:
        perm = {j: i for i, j in blocks}
        locs = []
        for j in range(k):
            B = _block(M, k, perm[j], j)
            locs.append(name_gate(_gf2(B), 1))
        cyc, seen = [], set()
        for s in range(k):
            if s in seen:
                continue
            c, t = [], s
            while t not in seen:
                seen.add(t)
                c.append(t)
                t = perm[t]
            if len(c) > 1:
                cyc.append(tuple(c))
        return {"type": "qubit permutation with local cliffords", "cycles": cyc,
                "local": {j: locs[j] for j in range(k) if locs[j] != "I"}}
    A, B, C, D = M[:k, :k], M[:k, k:], M[k:, :k], M[k:, k:]
    if not B.any() and not C.any():
        return {"type": "cnot circuit", "cnot_upper_bound": _gauss_ops(A), "A_rank": int(_rank(A))}
    if not A.any() and not D.any():
        return {"type": "hadamard layer composed with a cnot circuit", "cnot_upper_bound": _gauss_ops(B)}
    return {"type": "entangling", "qubits_coupled": sorted({q for i, j in blocks for q in (i, j)})}


def _gf2(B):
    import galois
    return galois.GF(2)(B.astype(int))


def _rank(A):
    m = A.copy() % 2
    r = 0
    for c in range(m.shape[1]):
        p = next((i for i in range(r, m.shape[0]) if m[i, c]), None)
        if p is None:
            continue
        m[[r, p]] = m[[p, r]]
        for i in range(m.shape[0]):
            if i != r and m[i, c]:
                m[i] ^= m[r]
        r += 1
    return r


def _gauss_ops(A):
    """row additions used to reduce an invertible binary matrix to identity, an upper bound on cnot count."""
    m = A.copy() % 2
    n = m.shape[0]
    ops = 0
    for c in range(n):
        p = next((i for i in range(c, n) if m[i, c]), None)
        if p is None:
            return None
        if p != c:
            m[c] ^= m[p]
            ops += 1
        for i in range(n):
            if i != c and m[i, c]:
                m[i] ^= m[c]
                ops += 1
    return ops


def classify_logical_group(matrices, k, max_points=3000, full_check_k=3):
    """summary of the group generated by 2k x 2k logical actions: order, clusters, per-cluster fullness, generator types."""
    mats = []
    seen = set()
    for M in matrices:
        A = _arr(M)
        key = A.tobytes()
        if key in seen or (A == np.eye(2 * k, dtype=np.uint8)).all():
            continue
        seen.add(key)
        mats.append(A)
    out = {"k": k, "nontrivial_generators": len(mats), "sp_order": sp_order(k)}
    if not mats:
        out.update({"order": 1, "order_status": "exact", "clusters": [], "generators": []})
        return out
    order, status = exact_order(mats, k, max_points)
    out["order"], out["order_status"] = order, status
    out["generators"] = [classify_generator(M, k) for M in mats]
    cl = []
    for q in clusters_of(mats, k):
        sub = [restrict(M, q, k) for M in mats]
        sub = [S for S in sub if not (S == np.eye(2 * len(q), dtype=np.uint8)).all()]
        entry = {"qubits": q, "m": len(q)}
        if not sub:
            entry.update({"order": 1, "full": False})
        else:
            o, st = exact_order(sub, len(q), max_points)
            entry["order"] = o
            entry["sp_order"] = sp_order(len(q))
            if o is not None:
                entry["full"] = o == sp_order(len(q))
            elif len(q) <= full_check_k:
                entry["full"] = generates_full_clifford([_gf2(S) for S in sub], len(q))["verdict"] == "full"
            else:
                entry["full"] = generates_full_clifford([_gf2(S) for S in sub], len(q), small_order_cap=0)["verdict"]
        cl.append(entry)
    out["clusters"] = cl
    out["acts_as_full_clifford"] = (len(cl) == 1 and cl[0]["m"] == k and cl[0].get("full") is True)
    return out


if __name__ == "__main__":
    import galois
    G = galois.GF(2)

    def lift(k, ops):
        M = np.eye(2 * k, dtype=np.uint8)
        for op in ops:
            M = (op @ M) % 2
        return M

    def H(k, q):
        M = np.eye(2 * k, dtype=np.uint8)
        M[[q, k + q]] = M[[k + q, q]]
        return M

    def S(k, q):
        M = np.eye(2 * k, dtype=np.uint8)
        M[k + q, q] = 1
        return M

    def CNOT(k, c, t):
        M = np.eye(2 * k, dtype=np.uint8)
        M[t, c] = 1
        M[k + c, k + t] = 1
        return M

    r = classify_logical_group([H(1, 0), S(1, 0)], 1)
    print("k=1 <H,S>:", r["order"], r["clusters"]); assert r["order"] == 6 and r["clusters"][0]["full"]
    r = classify_logical_group([H(2, 0), S(2, 0), H(2, 1), S(2, 1), CNOT(2, 0, 1)], 2)
    print("k=2 full:", r["order"], r["acts_as_full_clifford"]); assert r["order"] == 720 and r["acts_as_full_clifford"]
    r = classify_logical_group([H(3, 0), CNOT(3, 1, 2)], 3)
    print("k=3 H x CNOT:", r["order"], [(c["qubits"], c["order"]) for c in r["clusters"]])
    assert r["order"] == 4 and len(r["clusters"]) == 1 or r["order"] == 4
    P = np.zeros((8, 8), dtype=np.uint8)
    for i in range(4):
        P[(i + 1) % 4, i] = 1
        P[4 + (i + 1) % 4, 4 + i] = 1
    r = classify_logical_group([P], 4)
    print("k=4 cyclic permutation:", r["order"], r["generators"]); assert r["order"] == 4
    r = classify_logical_group([CNOT(4, 0, 1), CNOT(4, 1, 2), CNOT(4, 2, 3), CNOT(4, 3, 0), H(4, 0)], 4, max_points=3000)
    print("k=4 mixed:", r["order"], r["order_status"], r["clusters"])
    print("pass")
